class Solution:
    def maxValue(self, nums):
        n = len(nums)
        full = (1 << n) - 1
        AND = [0] * (1 << n)
        XOR = [0] * (1 << n)
        for msk in range(1, 1 << n):
            lb = msk & (-msk)
            i = lb.bit_length() - 1
            rest = msk ^ lb
            AND[msk] = nums[i] & AND[rest]
            XOR[msk] = nums[i] ^ XOR[rest]
        return max(AND[msk] + XOR[full ^ msk] for msk in range(1 << n))

