class Solution {
public:
    int maxValue(vector<int>& nums) {
        int n = nums.size(), full = (1 << n) - 1;
        vector<int> AND(1 << n, 0), XR(1 << n, 0);
        for (int msk = 1; msk <= full; msk++) {
            int lb = msk & (-msk), i = __builtin_ctz(msk), rest = msk ^ lb;
            AND[msk] = nums[i] & AND[rest];
            XR[msk] = nums[i] ^ XR[rest];
        }
        int ans = 0;
        for (int msk = 0; msk <= full; msk++) ans = max(ans, AND[msk] + XR[full ^ msk]);
        return ans;
    }
};

