class Solution {
    public int maxValue(int[] nums) {
        int n = nums.length, full = (1 << n) - 1;
        int[] AND = new int[1 << n], XR = new int[1 << n];
        for (int msk = 1; msk <= full; msk++) {
            int i = Integer.numberOfTrailingZeros(msk);
            int rest = msk & (msk - 1);
            AND[msk] = nums[i] & AND[rest];
            XR[msk] = nums[i] ^ XR[rest];
        }
        int ans = 0;
        for (int msk = 0; msk <= full; msk++) ans = Math.max(ans, AND[msk] + XR[full ^ msk]);
        return ans;
    }
}

