class Solution:
    def maxValue(self, nums):
        n = len(nums)
        best = 0
        def dfs(i, a, x, empty):
            nonlocal best
            if i == n:
                best = max(best, (0 if empty else a) + x)
                return
            dfs(i + 1, nums[i] if empty else a & nums[i], x, False)
            dfs(i + 1, a, x ^ nums[i], empty)
        dfs(0, 0, 0, True)
        return best

