class Solution {
    int best = 0;
    void dfs(vector<int>& nums, int i, int a, int x, bool empty) {
        if (i == (int)nums.size()) { best = max(best, (empty ? 0 : a) + x); return; }
        dfs(nums, i + 1, empty ? nums[i] : a & nums[i], x, false);
        dfs(nums, i + 1, a, x ^ nums[i], empty);
    }
public:
    int maxValue(vector<int>& nums) {
        dfs(nums, 0, 0, 0, true);
        return best;
    }
};

