class Solution {
    private int best = 0;
    private void dfs(int[] nums, int i, int a, int x, boolean empty) {
        if (i == nums.length) { best = Math.max(best, (empty ? 0 : a) + x); return; }
        dfs(nums, i + 1, empty ? nums[i] : a & nums[i], x, false);
        dfs(nums, i + 1, a, x ^ nums[i], empty);
    }
    public int maxValue(int[] nums) {
        dfs(nums, 0, 0, 0, true);
        return best;
    }
}

